/bin/bash -lc "mkdir -p supabase/functions/user-stats && apply_patch <<'PATCH'
*** Begin Patch
*** Update File: supabase/config.toml
@@
 [edge_runtime]
 enabled = true
 policy = \"per_worker\"
 inspector_port = 8083
 deno_version = 2
+
+[functions.user-stats]
+verify_jwt = false

 [analytics]
 enabled = true
 port = 54327
*** Add File: supabase/functions/user-stats/index.ts
+import { withSupabase } from \"npm:@supabase/server\";
+
+const userIdPattern = /"'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
+
+export default {
+  fetch: withSupabase({ auth: ["user", "secret"] }, async (req, ctx) => {
+    if (req.method !== "POST") {
+      return Response.json(
+        { error: "Method not allowed" },
+        { status: 405, headers: { Allow: "POST" } },
+      );
+    }
+
+    if (ctx.authMode === "user") {
+      const { data, error } = await ctx.supabase
+        .from("user_stats")
+        .select("user_id, metric, value");
+
+      if (error) {
+        return Response.json({ error: "Unable to load stats" }, { status: 500 });
+      }
+
+      return Response.json(data);
+    }
+
+    let body: unknown;
+    try {
+      body = await req.json();
+    } catch {
+      return Response.json({ error: "Invalid JSON body" }, { status: 400 });
+    }
+
+    const userId =
+      typeof body === "object" && body !== null && "user_id" in body
+        ? body.user_id
+        : undefined;
+
+    if (typeof userId !== "string" || !userIdPattern.test(userId)) {
+      return Response.json({ error: "A valid user_id is required" }, { status: 400 });
+    }
+
+    const { data, error } = await ctx.supabaseAdmin
+      .from("user_stats")
+      .select("user_id, metric, value")
+      .eq("user_id", userId);
+
+    if (error) {
+      return Response.json({ error: "Unable to load stats" }, { status: 500 });
+    }
+
+    return Response.json(data);
+  }),
+};
*** End Patch
PATCH
curl -fsSL https://supabase.com/changelog.md | head -80'
